  public RestaurantCatalog catalog;public Camera gameCamera;public RestaurantWorld world;
  public RestaurantGame Game {get;private set;}public string SavePath=>Path.Combine(Application.persistentDataPath,"restaurant-v1.json");
  SaveStore store;RectTransform safe,body,modal;TMP_Text wallet,subtitle,service,toast;TMP_Text[] cardLabels=new TMP_Text[3];Button[] cards=new Button[3];Image[] cardImages=new Image[3];
  readonly List<Action> refresh=new List<Action>();AudioSource audioSource,musicSource;static Sprite round;AudioClip coin,upgrade,nav;float accumulator,nextRefresh,nextSave,toastUntil,coinReady;int stage;string page="play";bool dirty=true;Rect previousSafe;
  static Color Cream=>Hex("#FFF8E9");static Color Ink=>Hex("#2E4941");static Color Green=>Hex("#397C5A");static Color Muted=>Hex("#7C8E82");static Color Peach=>Hex("#ECAD73");
  static Color Hex(string s){ColorUtility.TryParseHtmlString(s,out var c);return c;}
  void Awake(){
   Application.targetFrameRate=30;Screen.orientation=ScreenOrientation.Portrait;QualitySettings.vSyncCount=0;store=new SaveStore(SavePath);bool recovered=false;SaveState state=null;
   try{state=store.Read(out recovered);Game=new RestaurantGame(catalog,state);}catch(Exception e){Debug.LogError("Save recovery: "+e.Message);Game=new RestaurantGame(catalog);recovered=true;}
   Game.Feedback=Notify;Game.Paid=Paid;RestaurantDiagnostics.Event("session_start",new{version=Application.version});Game.Resume(Game.Now());world.game=Game;world.catalog=catalog;
   audioSource=gameObject.AddComponent<AudioSource>();audioSource.spatialBlend=0;coin=catalog.coinClip?catalog.coinClip:Tone("Coin",660,880,.08f);upgrade=catalog.upgradeClip?catalog.upgradeClip:Tone("Upgrade",523,1046,.18f);nav=catalog.tapClip?catalog.tapClip:Tone("Tap",370,420,.045f);
   musicSource=gameObject.AddComponent<AudioSource>();musicSource.clip=catalog.musicClip?catalog.musicClip:Music();musicSource.loop=true;musicSource.volume=catalog.musicVolume;musicSource.Play();BuildCanvas();ApplySettings();BuildPlay();if(store.HadUnreadableSave)Notify("Save unreadable. Original files were preserved for recovery.");else if(recovered)Notify("Recovered your saved progress from backup");if(Game.State.pendingOffline>0)OfflineDialog();else if(Game.State.tutorial<2)TutorialDialog();Save();
  }
  void Update(){
   if(Game==null)return;accumulator+=Mathf.Min(Time.unscaledDeltaTime,.5f);int ticks=0;while(accumulator>=.05f&&ticks++<10){Game.Tick(.05);accumulator-=.05f;}
   if(Time.unscaledTime>=nextRefresh){nextRefresh=Time.unscaledTime+.2f;Refresh();}
   if(Time.unscaledTime>=nextSave){nextSave=Time.unscaledTime+15;Save();}
   if(Screen.safeArea!=previousSafe)SafeArea();if(toast&&Time.unscaledTime>toastUntil)toast.text="";
   var keyboard=Keyboard.current;if(keyboard!=null){if(keyboard.escapeKey.wasPressedThisFrame)Back();if(page=="play"&&!modal){if(keyboard.digit1Key.wasPressedThisFrame)Buy(stage*3);if(keyboard.digit2Key.wasPressedThisFrame)Buy(stage*3+1);if(keyboard.digit3Key.wasPressedThisFrame)Buy(stage*3+2);}if(keyboard.mKey.wasPressedThisFrame&&!modal)Navigate("map");}
  }
  void LateUpdate(){if(gameCamera&&gameCamera.enabled)gameCamera.orthographicSize=8.8f/Mathf.Max(.5f,gameCamera.aspect);}
  void OnApplicationPause(bool pause){if(pause)Save();else if(Game!=null){Game.Resume(Game.Now());Save();if(Game.State.pendingOffline>0)OfflineDialog();}}
  void OnApplicationQuit(){Save();}
  public void Save(){if(Game==null)return;try{Game.State.utc=Game.Now();store.Write(Game.State);}catch(Exception e){Debug.LogError("Could not save restaurant: "+e.Message);Notify("Could not save. Please check free storage.");}}
  AudioClip Tone(string title,float a,float b,float duration){int count=(int)(44100*duration);var data=new float[count];for(int i=0;i<count;i++){float t=i/44100f,f=Mathf.Lerp(a,b,t/duration);data[i]=Mathf.Sin(2*Mathf.PI*f*t)*Mathf.Sin(Mathf.PI*i/count)*.11f;}var clip=AudioClip.Create(title,count,1,44100,false);clip.SetData(data,0);return clip;}
  void Sound(AudioClip clip){if(Game.State.sfx)audioSource.PlayOneShot(clip);}
  void Paid(int outlet,int step,double amount){dirty=true;if(outlet!=Game.State.selected)return;if(step==3){RestaurantDiagnostics.Event("service_reward",new{outlet,amount});Sound(upgrade);}else if(Time.unscaledTime>=coinReady){Sound(coin);coinReady=Time.unscaledTime+.15f;}}
  public void Notify(string message){if(toast){toast.text=message;toastUntil=Time.unscaledTime+3;}dirty=true;}
  void ApplySettings(){AudioListener.volume=1;if(musicSource)musicSource.mute=!Game.State.music;QualitySettings.shadows=Game.State.quality==0?ShadowQuality.Disable:ShadowQuality.HardOnly;foreach(var light in FindObjectsByType<Light>(FindObjectsSortMode.None))light.shadows=Game.State.quality==0?LightShadows.None:LightShadows.Hard;QualitySettings.antiAliasing=Game.State.quality==0?0:2;}
