   if(!FindAnyObjectByType<EventSystem>()){var es=new GameObject("Touch and mouse input",typeof(EventSystem),typeof(InputSystemUIInputModule));es.GetComponent<InputSystemUIInputModule>().AssignDefaultActions();}
   var canvas=new GameObject("Restaurant UI",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvas.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;var scale=canvas.GetComponent<CanvasScaler>();scale.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(720,1280);scale.matchWidthOrHeight=.5f;
   safe=Rect("Safe area",canvas.transform,Vector2.zero,Vector2.one);SafeArea();
   var top=Panel("Header",safe,new Vector2(0,.89f),Vector2.one,Cream);Text(top,"IDLE RESTAURANT",new Vector2(.04f,.63f),new Vector2(.7f,.95f),24,Ink);Button(top,"MENU",new Vector2(.81f,.57f),new Vector2(.98f,.97f),()=>Navigate("settings"),Green,16);
   wallet=Text(top,"",new Vector2(.04f,.05f),new Vector2(.64f,.59f),38,Green);subtitle=Text(top,"",new Vector2(.62f,.08f),new Vector2(.96f,.52f),22,Ink,TextAlignmentOptions.Right);
   body=Rect("Screen content",safe,new Vector2(0,.09f),new Vector2(1,.89f));
   var bottom=Panel("Navigation",safe,Vector2.zero,new Vector2(1,.075f),Cream);string[] names={"MAP","TEAM","PLAY","LAB","SHOP"};string[] pages={"map","managers","play","research","shop"};for(int i=0;i<5;i++){int n=i;Button(bottom,names[i],new Vector2(i/5f+.008f,.08f),new Vector2((i+1)/5f-.008f,.92f),()=>Navigate(pages[n]),i==2?Green:Hex("#E2E8D5"),18);}
   toast=Text(safe,"",new Vector2(.04f,.078f),new Vector2(.96f,.11f),20,Ink,TextAlignmentOptions.Center);toast.fontStyle=FontStyles.Bold;
  }
  void SafeArea(){previousSafe=Screen.safeArea;if(!safe)return;safe.anchorMin=new Vector2(previousSafe.x/Screen.width,previousSafe.y/Screen.height);safe.anchorMax=new Vector2(previousSafe.xMax/Screen.width,previousSafe.yMax/Screen.height);safe.offsetMin=safe.offsetMax=Vector2.zero;}
  RectTransform Rect(string name,Transform parent,Vector2 min,Vector2 max){var go=new GameObject(name,typeof(RectTransform));var r=go.GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=min;r.anchorMax=max;r.offsetMin=r.offsetMax=Vector2.zero;return r;}
  RectTransform Panel(string name,Transform parent,Vector2 min,Vector2 max,Color color){var r=Rect(name,parent,min,max);var image=r.gameObject.AddComponent<Image>();image.color=color;image.sprite=Rounded();image.type=Image.Type.Sliced;return r;}
  TMP_Text Text(Transform parent,string value,Vector2 min,Vector2 max,float size,Color color,TextAlignmentOptions align=TextAlignmentOptions.Left){var r=Rect("Label",parent,min,max);var t=r.gameObject.AddComponent<TextMeshProUGUI>();t.text=value;t.fontSize=size*(Game!=null&&Game.State.largeText?1.12f:1);t.color=color;t.alignment=align;t.enableWordWrapping=true;t.raycastTarget=false;t.margin=new Vector4(6,2,6,2);return t;}
  Button Button(Transform parent,string value,Vector2 min,Vector2 max,Action click,Color color,float size=22){var r=Panel(value,parent,min,max,color);var b=r.gameObject.AddComponent<Button>();var colors=b.colors;colors.highlightedColor=Hex("#E9EECF");colors.pressedColor=Hex("#CFDCAA");colors.disabledColor=Hex("#BEC4B7");b.colors=colors;Text(r,value,Vector2.zero,Vector2.one,size,color==Green?Cream:Ink,TextAlignmentOptions.Center);b.onClick.AddListener(()=>{Sound(nav);click();Save();dirty=true;});return b;}
  void ClearBody(){foreach(Transform child in body)Destroy(child.gameObject);refresh.Clear();service=null;Array.Clear(cardLabels,0,3);dirty=true;}
