   }Refresh();}
  static readonly string[] UpgradeNames={"Faster orders","Express orders","Order income","Faster delivery","Kitchen speed","Kitchen income","Faster seating","Express seating","Dining income"};
  string EffectText(int card,int level){double v=Economy.Effect(card,level);return card==0?v.ToString("0.00")+" / s":card==1||card==7?(v*100).ToString("0.0")+"%":card==3||card==4||card==6?v.ToString("0.00")+" s":"×"+v.ToString("0.0");}
  void Refresh(){if(!wallet)return;wallet.text=Economy.Money(Game.State.cash);subtitle.text="GEMS "+Game.State.gems+"  •  "+Economy.Money(Game.NetworkIncome())+" /m est.";
   if(page=="play"&&service){var s=Game.State.outlets[Game.State.selected];var d=catalog.outlets[Game.State.selected];service.text=s.clearClock>0?"SERVICE BONUS IN "+Math.Ceiling(s.clearClock)+"s":"ORDERS "+s.ordered+"    KITCHEN "+s.cooked+"    DINING "+s.seated+" / "+d.capacity;
    for(int j=0;j<3;j++){int card=stage*3+j,l=s.upgrades[card];bool max=l>=catalog.maxUpgrade;double price=Game.Cost(Game.State.selected,card);bool can=!max&&Game.State.cash>=price;cardImages[j].color=can?Green:Hex("#DCE0D2");cardLabels[j].color=can?Cream:Ink;cardLabels[j].text=UpgradeNames[card]+"\nLv. "+l+" / "+catalog.maxUpgrade+"\n"+EffectText(card,l)+(max?"":" → "+EffectText(card,l+1))+"\n"+(max?"MAX LEVEL":can?"BUY  "+Economy.Money(price):"NEED  "+Economy.Money(price));cards[j].interactable=!max;}
   }foreach(var action in refresh)action();dirty=false;
  }
