  void BuildSettings(){var p=PageTitle("Settings","Progress saves automatically • Android 11+");var content=Scroll(p,9,125);Setting(content,0,"Sound effects",()=>Game.State.sfx,v=>Game.State.sfx=v);Setting(content,1,"Music",()=>Game.State.music,v=>{Game.State.music=v;ApplySettings();});Setting(content,2,"Haptics",()=>Game.State.haptics,v=>Game.State.haptics=v);Setting(content,3,"Reduce motion",()=>Game.State.reducedMotion,v=>Game.State.reducedMotion=v);Setting(content,4,"Larger text",()=>Game.State.largeText,v=>{Game.State.largeText=v;Navigate("settings");});var q=ListRow(content,5,125);Text(q,"Graphics quality",new Vector2(.02f,.1f),new Vector2(.7f,.9f),26,Ink);Button(q,Game.State.quality==0?"LOW":"MEDIUM",new Vector2(.73f,.15f),new Vector2(.98f,.85f),()=>{Game.State.quality=1-Game.State.quality;ApplySettings();Navigate("settings");},Green,18);var tut=ListRow(content,6,125);Button(tut,"Replay welcome guide",new Vector2(.02f,.1f),new Vector2(.98f,.9f),TutorialDialog,Green);var privacy=ListRow(content,7,125);Button(privacy,"Privacy and service status",new Vector2(.02f,.1f),new Vector2(.98f,.9f),()=>Dialog("Service status","This build saves progress locally. Purchases and rewarded ads are development simulations. Production services and online analytics are not configured. No account data is sent. Publisher privacy policy and consent setup remain release blockers.","CLOSE",CloseModal),Green,21);}
  void Setting(RectTransform content,int i,string title,Func<bool> read,Action<bool> set){var row=ListRow(content,i,125);Text(row,title,new Vector2(.02f,.1f),new Vector2(.7f,.9f),26,Ink);var b=Button(row,"",new Vector2(.73f,.15f),new Vector2(.98f,.85f),()=>set(!read()),Green,20);var t=b.GetComponentInChildren<TMP_Text>();refresh.Add(()=>t.text=read()?"ON":"OFF");}
  void BuildShop(){var p=PageTitle("Restaurant shop",Debug.isDebugBuild?"DEMO PURCHASES • test IDs • no real charges":"Store products are not configured");var content=Scroll(p,catalog.offers.Length+2,160);for(int i=0;i<catalog.offers.Length;i++){var offer=catalog.offers[i];var row=ListRow(content,i,160);Text(row,offer.title,new Vector2(.02f,.46f),new Vector2(.72f,.96f),26,Ink);Text(row,offer.type+" • "+offer.id,new Vector2(.02f,.03f),new Vector2(.72f,.48f),17,Muted);Button(row,Debug.isDebugBuild?"DEMO BUY":"DETAILS",new Vector2(.73f,.17f),new Vector2(.98f,.83f),()=>DemoPurchaseDialog(offer),Green,18);}var ad=ListRow(content,catalog.offers.Length,160);Text(ad,"10 gems • rewarded",new Vector2(.02f,.42f),new Vector2(.72f,.96f),25,Ink);Text(ad,"Voluntary ad • proposed daily limit 3",new Vector2(.02f,.03f),new Vector2(.72f,.46f),18,Muted);Button(ad,"WATCH",new Vector2(.73f,.17f),new Vector2(.98f,.83f),()=>RewardDialog("gems"),Green,19);var cash=ListRow(content,catalog.offers.Length+1,160);Text(cash,"Cash deliveries",new Vector2(.02f,.42f),new Vector2(.72f,.96f),25,Ink);Text(cash,"15 min / 1 h / 2 h • 10 / 30 / 50 gems",new Vector2(.02f,.03f),new Vector2(.72f,.46f),18,Muted);Button(cash,"SELECT",new Vector2(.73f,.17f),new Vector2(.98f,.83f),CashDialog,Green,19);}
  void DemoPurchaseDialog(OfferDefinition offer){
#if UNITY_EDITOR || DEVELOPMENT_BUILD
   Dialog("Demo purchase",offer.title+"\nTest product: "+offer.id+"\nNo money is charged. This reward is for local testing only.","CONFIRM DEMO",()=>{var snapshot=Newtonsoft.Json.JsonConvert.SerializeObject(Game.State);try{if(!Game.DemoPurchase(offer.id,"demo-"+Guid.NewGuid().ToString("N")))throw new Exception("Unknown demo product");Game.State.utc=Game.Now();store.Write(Game.State);CloseModal();Notify("Demo purchase granted");Sound(upgrade);}catch(Exception){Game.State=Newtonsoft.Json.JsonConvert.DeserializeObject<SaveState>(snapshot);Notify("Purchase could not be saved. No reward was granted.");}});
#else
   Dialog("Store unavailable","Production products are not configured. No charge or reward will be applied.","CLOSE",CloseModal);
#endif
  }
  void CashDialog(){Dialog("Cash delivery","Cash uses estimated current network income. Select 15 minutes for 10 gems, 1 hour for 30 gems, or 2 hours for 50 gems.","15 MIN • 10 gems",()=>Cash(15,10));Button(modal,"1 HOUR • 30 gems",new Vector2(.1f,.13f),new Vector2(.9f,.23f),()=>Cash(60,30),Peach,20);Button(modal,"2 HOURS • 50 gems",new Vector2(.1f,.02f),new Vector2(.9f,.12f),()=>Cash(120,50),Peach,20);}
  void Cash(int minutes,int gems){if(Game.State.gems<gems){Notify("Needs "+gems+" gems");return;}Game.State.gems-=gems;Game.State.cash+=Game.NetworkIncome()*minutes;CloseModal();Notify("Cash delivered");}
  void RewardDialog(string type){
#if UNITY_EDITOR || DEVELOPMENT_BUILD
   Dialog("Development ad test","This is a local test, not a real advertisement. Simulate a completed rewarded ad? Release builds cannot use this test grant.","SIMULATE COMPLETION",()=>{double now=Game.Now();if(now<Game.State.adReady){Notify("Reward cooldown active");return;}if(type=="gems"){int day=(int)(now/86400);if(Game.State.dailyDay!=day){Game.State.dailyDay=day;Game.State.dailyAds=0;}if(Game.State.dailyAds>=3){Notify("Daily test limit reached");return;}Game.State.dailyAds++;Game.State.gems+=10;}else Game.State.boostUntil=now+catalog.rewardedBoostSeconds;Game.State.adReady=now+catalog.rewardedCooldownSeconds;Save();CloseModal();Notify("Development reward applied");});
#else
   Dialog("Reward unavailable","Advertising is not configured. Please try again in a configured release.","CLOSE",CloseModal);
#endif
  }
  void OfflineDialog(){Dialog("Welcome back", "Your team kept the restaurant going. Offline earnings: "+Economy.Money(Game.State.pendingOffline)+". Standard earnings are capped at two hours at 25% of estimated income.","COLLECT",()=>{double value=Game.ClaimOffline();Save();CloseModal();Notify("Collected "+Economy.Money(value));});}
  void TutorialDialog(){Dialog("Welcome, restaurateur!","Guests place orders, collect food and dine. Each stage earns cash. Upgrade the green BUY cards to improve your service. Grey NEED cards show the cash you still need. Open the map for your next outlet.\n\nEditor: 1 / 2 / 3 buy upgrades, M opens the map, Esc goes back.","LET’S COOK",()=>{Game.State.tutorial=Math.Max(1,Game.State.tutorial);CloseModal();Save();});}
  void Dialog(string title,string message,string action,Action click){if(modal)CloseModal();var shade=Panel("Dialog shade",safe,Vector2.zero,Vector2.one,new Color(0,0,0,.48f));modal=Panel("Dialog",shade,new Vector2(.05f,.24f),new Vector2(.95f,.76f),Cream);Text(modal,title,new Vector2(.06f,.78f),new Vector2(.94f,.97f),33,Ink);Text(modal,message,new Vector2(.07f,.31f),new Vector2(.93f,.78f),23,Ink);Button(modal,action,new Vector2(.08f,.24f),new Vector2(.92f,.36f),click,Green,22);Button(modal,"×",new Vector2(.85f,.88f),new Vector2(.97f,.99f),CloseModal,Peach,23);}

  static Sprite Rounded(){if(round)return round;int size=48;var texture=new Texture2D(size,size,TextureFormat.RGBA32,false);for(int y=0;y<size;y++)for(int x=0;x<size;x++){float dx=Mathf.Max(12-x,x-35),dy=Mathf.Max(12-y,y-35);float distance=Mathf.Sqrt(Mathf.Max(0,dx)*Mathf.Max(0,dx)+Mathf.Max(0,dy)*Mathf.Max(0,dy));texture.SetPixel(x,y,new Color(1,1,1,Mathf.Clamp01(12.5f-distance)));}texture.Apply();round=Sprite.Create(texture,new Rect(0,0,size,size),Vector2.one*.5f,100,0,SpriteMeshType.FullRect,new Vector4(16,16,16,16));return round;}
  AudioClip Music(){int rate=22050;float length=16;var data=new float[(int)(rate*length)];int[] notes={60,64,67,71,57,60,64,67,53,57,60,64,55,59,62,67};for(int i=0;i<data.Length;i++){float t=i/(float)rate;int beat=(int)(t*2);float local=t%0.5f,env=Mathf.Exp(-local*8);float hz=440*Mathf.Pow(2,(notes[beat%notes.Length]-69)/12f);data[i]=(.14f*Mathf.Sin(2*Mathf.PI*hz*t)+.04f*Mathf.Sin(2*Mathf.PI*hz*2*t))*env;}var clip=AudioClip.Create("Original cozy marimba loop",data.Length,1,rate,false);clip.SetData(data,0);return clip;}
  void CloseModal(){if(modal)Destroy(modal.parent.gameObject);modal=null;Refresh();}
